class Counter { int value = 0; }        // shared, no synchronization

Counter c = new Counter();
Runnable job = () -> { for (int i = 0; i < 1000; i++) c.value++; };

Thread t1 = new Thread(job);
Thread t2 = new Thread(job);
t1.start();
t2.run();                              // note: run(), not start()
t1.join();
System.out.println(c.value);

